insert into news_item (title, body, author, original_date, source_site, source_url) values ('New teamspeak server', 'We''ve migrated into a new teamspeak server due to our old server constantly crashing, lagging out during events etc. We''ve reason to believe someone targeted us and "ddosed" the teamspeak server. Our provider informed us that the attack was directed towards 9989, our old teamspeak server port. If you need the new teamspeak info, message a member via steam or post in the shoutbox. We will no longer be giving out the teamspeak publicly on our site, forums or any where on the web for that matter. Sorry for the Inconvenience, I hope all of you have an awesome day and I''ll see you dudes at the next event!', 'RiveR', '2015-07-05', 'coldstream.enjin.com', null);
